const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const express = require('express');
const Database = require('better-sqlite3');
const XLSX = require('xlsx');

const PORT = 3000;
const DB_PATH = '/app/dropline.db';
const SEED_PATH = '/assets/artifacts/dropline_seed.xlsx';
const PUBLIC_DIR = path.join(__dirname, 'public');
const BOARD_COLUMNS = 7;
const BOARD_ROWS = 6;
const CELL_COUNT = BOARD_COLUMNS * BOARD_ROWS;

const app = express();
app.use(express.json({ limit: '32kb' }));
app.use(express.static(PUBLIC_DIR));

const db = new Database(DB_PATH);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

db.exec(`
  CREATE TABLE IF NOT EXISTS accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    password_salt TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    created_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS sessions (
    token TEXT PRIMARY KEY,
    account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    revoked_at TEXT
  );

  CREATE TABLE IF NOT EXISTS games (
    account_id INTEGER PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
    board_json TEXT NOT NULL,
    turn TEXT NOT NULL,
    status TEXT NOT NULL,
    result TEXT NOT NULL,
    winning_cells_json TEXT NOT NULL,
    red_wins INTEGER NOT NULL,
    yellow_wins INTEGER NOT NULL,
    draws INTEGER NOT NULL,
    applied_history_json TEXT NOT NULL,
    redo_history_json TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS actions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    type TEXT NOT NULL,
    payload_json TEXT NOT NULL,
    created_at TEXT NOT NULL
  );
`);

const selectAccountByEmail = db.prepare('SELECT * FROM accounts WHERE email = ?');
const selectAccountByToken = db.prepare(`
  SELECT a.id, a.email, a.name, s.token
  FROM sessions s
  JOIN accounts a ON a.id = s.account_id
  WHERE s.token = ? AND s.revoked_at IS NULL
`);
const insertAccount = db.prepare(`
  INSERT INTO accounts (email, name, password_salt, password_hash, created_at)
  VALUES (?, ?, ?, ?, ?)
`);
const insertSession = db.prepare(`
  INSERT INTO sessions (token, account_id, created_at, revoked_at)
  VALUES (?, ?, ?, NULL)
`);
const revokeSession = db.prepare('UPDATE sessions SET revoked_at = ? WHERE token = ? AND revoked_at IS NULL');
const selectGame = db.prepare('SELECT * FROM games WHERE account_id = ?');
const insertGame = db.prepare(`
  INSERT OR IGNORE INTO games (
    account_id, board_json, turn, status, result, winning_cells_json,
    red_wins, yellow_wins, draws, applied_history_json, redo_history_json, updated_at
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
`);
const updateGame = db.prepare(`
  UPDATE games
  SET board_json = ?, turn = ?, status = ?, result = ?, winning_cells_json = ?,
      red_wins = ?, yellow_wins = ?, draws = ?, applied_history_json = ?,
      redo_history_json = ?, updated_at = ?
  WHERE account_id = ?
`);
const insertAction = db.prepare(`
  INSERT INTO actions (account_id, type, payload_json, created_at)
  VALUES (?, ?, ?, ?)
`);

function nowIso() {
  return new Date().toISOString();
}

function normalizeEmail(value) {
  return String(value || '').trim().toLowerCase();
}

function trimString(value) {
  return String(value || '').trim();
}

function gameError(status, message) {
  const error = new Error(message);
  error.status = status;
  return error;
}

function hashPassword(password, salt = crypto.randomBytes(16).toString('hex')) {
  const hash = crypto.scryptSync(String(password), salt, 64).toString('hex');
  return { salt, hash };
}

function verifyPassword(password, account) {
  const expected = Buffer.from(account.password_hash, 'hex');
  const actual = crypto.scryptSync(String(password), account.password_salt, 64);
  return expected.length === actual.length && crypto.timingSafeEqual(expected, actual);
}

function createEmptyBoard() {
  return Array(CELL_COUNT).fill(null);
}

function parseWinningCells(value) {
  const text = String(value || '').trim();
  if (!text || text.toLowerCase() === 'none') {
    return [];
  }
  return text
    .split(/[;,]/)
    .map((part) => Number(part.trim()))
    .filter((part) => Number.isInteger(part) && part >= 0 && part < CELL_COUNT);
}

function parseBoardSeed(value) {
  const text = String(value || '').trim().toLowerCase();
  if (text === '42 empty cells') {
    return createEmptyBoard();
  }
  throw new Error(`Unsupported seed board description: ${value}`);
}

function buildInitialGameState(row) {
  const turn = trimString(row['Current player']) || 'Red';
  const status = (trimString(row.Status) || 'active').toLowerCase();
  const board = parseBoardSeed(row.Board);
  const winningCells = parseWinningCells(row['Winning cells']);
  const redWins = Number(row['Red wins']) || 0;
  const yellowWins = Number(row['Yellow wins']) || 0;
  const draws = Number(row.Draws) || 0;
  return {
    board,
    turn,
    status,
    result: status === 'active' ? '' : status,
    winningCells,
    redWins,
    yellowWins,
    draws,
    appliedMoves: [],
    redoMoves: []
  };
}

function deserializeGame(row) {
  return {
    board: JSON.parse(row.board_json),
    turn: row.turn,
    status: row.status,
    result: row.result,
    winningCells: JSON.parse(row.winning_cells_json),
    redWins: row.red_wins,
    yellowWins: row.yellow_wins,
    draws: row.draws,
    appliedMoves: JSON.parse(row.applied_history_json),
    redoMoves: JSON.parse(row.redo_history_json)
  };
}

function persistGame(accountId, state) {
  updateGame.run(
    JSON.stringify(state.board),
    state.turn,
    state.status,
    state.result,
    JSON.stringify(state.winningCells),
    state.redWins,
    state.yellowWins,
    state.draws,
    JSON.stringify(state.appliedMoves),
    JSON.stringify(state.redoMoves),
    nowIso(),
    accountId
  );
}

function oppositeColor(color) {
  return color === 'Red' ? 'Yellow' : 'Red';
}

function cellIndex(row, column) {
  return row * BOARD_COLUMNS + column;
}

function findLandingRow(board, column) {
  for (let row = BOARD_ROWS - 1; row >= 0; row -= 1) {
    if (!board[cellIndex(row, column)]) {
      return row;
    }
  }
  return -1;
}

function lineWindow(line, placedIndex) {
  const position = line.indexOf(placedIndex);
  if (position === -1) {
    return line.slice(0, 4);
  }
  const start = Math.min(Math.max(position - 3, 0), line.length - 4);
  return line.slice(start, start + 4);
}

function findWinningCells(board, placedIndex, color) {
  const row = Math.floor(placedIndex / BOARD_COLUMNS);
  const column = placedIndex % BOARD_COLUMNS;
  const directions = [
    [0, 1],
    [1, 0],
    [1, 1],
    [1, -1]
  ];

  for (const [dr, dc] of directions) {
    const line = [placedIndex];

    let r = row - dr;
    let c = column - dc;
    while (r >= 0 && r < BOARD_ROWS && c >= 0 && c < BOARD_COLUMNS && board[cellIndex(r, c)] === color) {
      line.unshift(cellIndex(r, c));
      r -= dr;
      c -= dc;
    }

    r = row + dr;
    c = column + dc;
    while (r >= 0 && r < BOARD_ROWS && c >= 0 && c < BOARD_COLUMNS && board[cellIndex(r, c)] === color) {
      line.push(cellIndex(r, c));
      r += dr;
      c += dc;
    }

    if (line.length >= 4) {
      return lineWindow(line, placedIndex);
    }
  }

  return [];
}

function boardIsFull(board) {
  return board.every(Boolean);
}

function ensureGameSeed() {
  const workbook = XLSX.readFile(SEED_PATH);
  const accountSheet = workbook.Sheets.Accounts;
  const gameSheet = workbook.Sheets['Initial Game State'];
  const accountRows = XLSX.utils.sheet_to_json(accountSheet, { defval: '' });
  const gameRows = XLSX.utils.sheet_to_json(gameSheet, { defval: '' });

  const seedAccounts = new Map();
  for (const row of gameRows) {
    seedAccounts.set(normalizeEmail(row['Account email']), row);
  }

  for (const row of accountRows) {
    const email = normalizeEmail(row.Email);
    const name = trimString(row.Name);
    const password = String(row.Password || '');
    if (!email || !name) {
      continue;
    }

    let account = selectAccountByEmail.get(email);
    if (!account) {
      const { salt, hash } = hashPassword(password);
      insertAccount.run(email, name, salt, hash, nowIso());
      account = selectAccountByEmail.get(email);
    }

    const seedStateRow = seedAccounts.get(email);
    if (!seedStateRow) {
      continue;
    }

    const initialState = buildInitialGameState(seedStateRow);
    insertGame.run(
      account.id,
      JSON.stringify(initialState.board),
      initialState.turn,
      initialState.status,
      initialState.result,
      JSON.stringify(initialState.winningCells),
      initialState.redWins,
      initialState.yellowWins,
      initialState.draws,
      JSON.stringify(initialState.appliedMoves),
      JSON.stringify(initialState.redoMoves),
      nowIso()
    );
  }
}

function getOrCreateGame(accountId) {
  let row = selectGame.get(accountId);
  if (!row) {
    const fallbackState = {
      board: createEmptyBoard(),
      turn: 'Red',
      status: 'active',
      result: '',
      winningCells: [],
      redWins: 0,
      yellowWins: 0,
      draws: 0,
      appliedMoves: [],
      redoMoves: []
    };
    insertGame.run(
      accountId,
      JSON.stringify(fallbackState.board),
      fallbackState.turn,
      fallbackState.status,
      fallbackState.result,
      JSON.stringify(fallbackState.winningCells),
      fallbackState.redWins,
      fallbackState.yellowWins,
      fallbackState.draws,
      JSON.stringify(fallbackState.appliedMoves),
      JSON.stringify(fallbackState.redoMoves),
      nowIso()
    );
    row = selectGame.get(accountId);
  }
  return row;
}

function publicState(account, game) {
  return {
    account: {
      name: account.name,
      email: account.email
    },
    board: game.board,
    turn: game.turn,
    status: game.status,
    result: game.result,
    winningCells: game.winningCells,
    totals: {
      redWins: game.redWins,
      yellowWins: game.yellowWins,
      draws: game.draws
    },
    appliedMoves: game.appliedMoves,
    redoCount: game.redoMoves.length,
    canUndo: game.appliedMoves.length > 0,
    canRedo: game.redoMoves.length > 0,
    statusMessage: game.status === 'active' ? `${game.turn}'s turn` : game.result
  };
}

function currentAccountFromToken(req) {
  const header = String(req.headers.authorization || '');
  if (!header.startsWith('Bearer ')) {
    return null;
  }
  const token = header.slice(7).trim();
  if (!token) {
    return null;
  }
  return selectAccountByToken.get(token) || null;
}

function requireAuth(req, res, next) {
  const account = currentAccountFromToken(req);
  if (!account) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.account = account;
  next();
}

function withGameMutation(type, handler) {
  return db.transaction((accountId, payload) => {
    const row = getOrCreateGame(accountId);
    const state = deserializeGame(row);
    const result = handler(state, payload);
    persistGame(accountId, state);
    insertAction.run(accountId, type, JSON.stringify(payload || {}), nowIso());
    return result || state;
  });
}

const applyMove = withGameMutation('move', (state, payload) => {
  const column = Number(payload.column);
  if (!Number.isInteger(column) || column < 1 || column > BOARD_COLUMNS) {
    throw gameError(400, 'Invalid column');
  }
  if (state.status !== 'active') {
    throw gameError(409, 'Game is over');
  }

  const columnIndex = column - 1;
  const landingRow = findLandingRow(state.board, columnIndex);
  if (landingRow === -1) {
    throw gameError(409, `Column ${column} is full`);
  }

  const color = state.turn;
  const index = cellIndex(landingRow, columnIndex);
  state.board[index] = color;
  const move = {
    moveNumber: state.appliedMoves.length + 1,
    color,
    column,
    row: landingRow + 1,
    cellIndex: index
  };
  state.appliedMoves.push(move);
  state.redoMoves = [];

  const winningCells = findWinningCells(state.board, index, color);
  if (winningCells.length === 4) {
    state.status = 'won';
    state.result = `${color} wins`;
    state.winningCells = winningCells;
    if (color === 'Red') {
      state.redWins += 1;
    } else {
      state.yellowWins += 1;
    }
  } else if (boardIsFull(state.board)) {
    state.status = 'draw';
    state.result = 'Draw';
    state.winningCells = [];
    state.draws += 1;
  } else {
    state.status = 'active';
    state.result = '';
    state.winningCells = [];
  }

  state.turn = oppositeColor(color);
  return state;
});

const undoMove = withGameMutation('undo', (state) => {
  if (state.appliedMoves.length === 0) {
    throw gameError(409, 'Nothing to undo');
  }

  const undone = state.appliedMoves.pop();
  state.redoMoves.push(undone);
  state.board[undone.cellIndex] = null;

  if (state.status === 'won') {
    if (undone.color === 'Red') {
      state.redWins -= 1;
    } else {
      state.yellowWins -= 1;
    }
  } else if (state.status === 'draw') {
    state.draws -= 1;
  }

  state.status = 'active';
  state.result = '';
  state.winningCells = [];
  state.turn = undone.color;
  return state;
});

const redoMove = withGameMutation('redo', (state) => {
  if (state.redoMoves.length === 0) {
    throw gameError(409, 'Nothing to redo');
  }
  if (state.status !== 'active') {
    throw gameError(409, 'Game is over');
  }

  const move = state.redoMoves.pop();
  state.board[move.cellIndex] = move.color;
  state.appliedMoves.push(move);

  const winningCells = findWinningCells(state.board, move.cellIndex, move.color);
  if (winningCells.length === 4) {
    state.status = 'won';
    state.result = `${move.color} wins`;
    state.winningCells = winningCells;
    if (move.color === 'Red') {
      state.redWins += 1;
    } else {
      state.yellowWins += 1;
    }
  } else if (boardIsFull(state.board)) {
    state.status = 'draw';
    state.result = 'Draw';
    state.winningCells = [];
    state.draws += 1;
  } else {
    state.status = 'active';
    state.result = '';
    state.winningCells = [];
  }

  state.turn = oppositeColor(move.color);
  return state;
});

const newGame = withGameMutation('new-game', (state) => {
  state.board = createEmptyBoard();
  state.turn = 'Red';
  state.status = 'active';
  state.result = '';
  state.winningCells = [];
  state.appliedMoves = [];
  state.redoMoves = [];
  return state;
});

function handleRoute(fn) {
  return (req, res, next) => {
    try {
      fn(req, res, next);
    } catch (error) {
      next(error);
    }
  };
}

app.get('/health', handleRoute((req, res) => {
  res.json({ ok: true });
}));

app.post('/api/login', handleRoute((req, res) => {
  const email = normalizeEmail(req.body && req.body.email);
  const password = String(req.body && req.body.password ? req.body.password : '');
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  const account = selectAccountByEmail.get(email);
  if (!account || !verifyPassword(password, account)) {
    return res.status(401).json({ error: 'Incorrect email or password' });
  }

  const token = crypto.randomBytes(32).toString('base64url');
  insertSession.run(token, account.id, nowIso());
  const state = deserializeGame(getOrCreateGame(account.id));
  res.json({
    token,
    account: {
      name: account.name,
      email: account.email
    },
    state: publicState(account, state)
  });
}));

app.post('/api/logout', requireAuth, handleRoute((req, res) => {
  const token = String(req.headers.authorization || '').slice(7).trim();
  revokeSession.run(nowIso(), token);
  res.json({ ok: true });
}));

app.get('/api/state', requireAuth, handleRoute((req, res) => {
  const account = req.account;
  const state = deserializeGame(getOrCreateGame(account.id));
  res.json(publicState(account, state));
}));

app.post('/api/move', requireAuth, handleRoute((req, res) => {
  const state = applyMove(req.account.id, { column: Number(req.body && req.body.column) });
  res.json(publicState(req.account, state));
}));

app.post('/api/undo', requireAuth, handleRoute((req, res) => {
  const state = undoMove(req.account.id, {});
  res.json(publicState(req.account, state));
}));

app.post('/api/redo', requireAuth, handleRoute((req, res) => {
  const state = redoMove(req.account.id, {});
  res.json(publicState(req.account, state));
}));

app.post('/api/new-game', requireAuth, handleRoute((req, res) => {
  const state = newGame(req.account.id, {});
  res.json(publicState(req.account, state));
}));

app.get('/', (req, res, next) => {
  res.sendFile(path.join(PUBLIC_DIR, 'index.html'));
});

app.use((error, req, res, next) => {
  if (error && error.status) {
    return res.status(error.status).json({ error: error.message });
  }
  console.error(error);
  res.status(500).json({ error: 'Internal server error' });
});

ensureGameSeed();

app.listen(PORT, '0.0.0.0', () => {
  console.log(`DropLine listening on http://0.0.0.0:${PORT}`);
});

:root {
  color-scheme: dark;
  --bg: #08111f;
  --bg-elevated: rgba(12, 21, 40, 0.86);
  --panel-border: rgba(148, 173, 226, 0.18);
  --text: #eef3ff;
  --muted: #a8b5d1;
  --accent: #67a0ff;
  --accent-strong: #3c7dff;
  --red: #e85a68;
  --yellow: #f0c542;
  --board: #173d7a;
  --cell-empty: #091427;
  --cell-shadow: rgba(0, 0, 0, 0.28);
  --success: #7ef0b4;
  --danger: #ff8c8c;
  --radius: 20px;
  --shadow: 0 18px 40px rgba(0, 0, 0, 0.28);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background:
    radial-gradient(circle at top, rgba(68, 110, 191, 0.35), transparent 42%),
    linear-gradient(180deg, #07101d 0%, #0b1729 45%, #09111d 100%);
  color: var(--text);
}

button,
input {
  font: inherit;
}

button {
  border: 0;
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.page-shell {
  width: min(1100px, 100%);
  margin: 0 auto;
  padding: 16px;
}

.app-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.app-header h1,
.panel h2 {
  margin: 0;
  line-height: 1.08;
}

.app-header h1 {
  font-size: clamp(1.6rem, 3vw, 2.6rem);
  max-width: 20ch;
}

.eyebrow {
  margin: 0 0 0.35rem;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.74rem;
  font-weight: 700;
}

.panel {
  background: var(--bg-elevated);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
}

.auth-panel {
  display: grid;
  gap: 1.25rem;
  padding: 1.25rem;
  max-width: 42rem;
  margin: 0 auto;
}

.panel-copy p:last-child {
  margin-bottom: 0;
}

.stacked-form {
  display: grid;
  gap: 0.9rem;
}

.stacked-form label {
  display: grid;
  gap: 0.45rem;
  color: var(--muted);
  font-size: 0.96rem;
}

.stacked-form input {
  width: 100%;
  border-radius: 14px;
  border: 1px solid rgba(175, 195, 240, 0.18);
  background: rgba(8, 15, 28, 0.88);
  color: var(--text);
  padding: 0.9rem 1rem;
  outline: none;
}

.stacked-form input:focus,
button:focus-visible {
  box-shadow: 0 0 0 3px rgba(103, 160, 255, 0.35);
}

.primary-button,
.secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.9rem;
  border-radius: 14px;
  padding: 0.8rem 1rem;
  color: var(--text);
  transition: transform 150ms ease, background-color 150ms ease, border-color 150ms ease;
}

.primary-button {
  background: linear-gradient(180deg, var(--accent), var(--accent-strong));
  color: #08111f;
  font-weight: 800;
}

.secondary-button {
  background: rgba(159, 182, 226, 0.12);
  border: 1px solid rgba(159, 182, 226, 0.18);
}

.primary-button:not(:disabled):hover,
.secondary-button:not(:disabled):hover {
  transform: translateY(-1px);
}

.form-feedback,
.feedback-text,
.status-text,
.muted {
  margin: 0;
}

.form-feedback,
.feedback-text {
  min-height: 1.4rem;
}

.form-feedback,
.feedback-text {
  color: var(--danger);
}

.status-text {
  font-size: 1.15rem;
  font-weight: 800;
}

.muted {
  color: var(--muted);
}

.game-shell {
  display: grid;
  gap: 1rem;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.1rem;
}

.account-block h2 {
  font-size: clamp(1.2rem, 2vw, 1.6rem);
  margin-bottom: 0.35rem;
}

.game-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(16rem, 0.85fr);
  gap: 1rem;
  align-items: start;
}

.board-panel,
.sidebar > .panel {
  padding: 1rem;
}

.board-panel {
  display: grid;
  gap: 1rem;
}

.board-status {
  display: grid;
  gap: 0.3rem;
}

.column-controls {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.35rem;
}

.column-controls button {
  min-height: 3rem;
  padding: 0.5rem 0.25rem;
  font-size: 0.8rem;
  line-height: 1.05;
  text-align: center;
}

.board-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.4rem;
  width: min(100%, 32rem);
  margin: 0 auto;
  padding: 0.75rem;
  border-radius: 22px;
  background: linear-gradient(180deg, #255db0 0%, #1f4f99 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.cell {
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 32% 32%, rgba(40, 67, 121, 0.55), var(--cell-empty) 64%);
  box-shadow: inset 0 0 0 4px rgba(255, 255, 255, 0.03), 0 4px 10px var(--cell-shadow);
}

.cell.red {
  background: radial-gradient(circle at 32% 32%, #ffd0d4 0%, #f06e7a 28%, #d92f43 72%, #a9182c 100%);
}

.cell.yellow {
  background: radial-gradient(circle at 32% 32%, #fff6c8 0%, #ffd94e 28%, #d9a800 72%, #9d7700 100%);
}

.cell.winning {
  box-shadow:
    inset 0 0 0 4px rgba(255, 255, 255, 0.24),
    0 0 0 3px rgba(255, 255, 255, 0.8),
    0 6px 16px rgba(0, 0, 0, 0.3);
}

.sidebar {
  display: grid;
  gap: 1rem;
}

.section-heading {
  margin-bottom: 0.75rem;
}

.totals-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.65rem;
}

.total-card {
  border-radius: 16px;
  padding: 0.85rem;
  display: grid;
  gap: 0.4rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.total-card span {
  color: var(--muted);
  font-size: 0.9rem;
}

.total-card strong {
  font-size: 1.9rem;
  line-height: 1;
}

.total-card.red strong {
  color: var(--red);
}

.total-card.yellow strong {
  color: var(--yellow);
}

.total-card.neutral strong {
  color: var(--success);
}

.actions-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
}

.history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
  max-height: 24rem;
  overflow: auto;
}

.history-item {
  border-radius: 16px;
  padding: 0.8rem 0.9rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: grid;
  gap: 0.25rem;
}

.history-item strong {
  font-size: 0.98rem;
}

.history-item span {
  color: var(--muted);
  font-size: 0.93rem;
}

.empty-history {
  color: var(--muted);
  padding: 0.8rem 0.9rem;
}

[hidden] {
  display: none !important;
}

@media (max-width: 900px) {
  .game-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .history-panel {
    grid-column: 1 / -1;
  }
}

@media (max-width: 640px) {
  .page-shell {
    padding: 12px;
  }

  .game-header,
  .auth-panel {
    padding: 1rem;
  }

  .game-header {
    flex-direction: column;
    align-items: start;
  }

  .column-controls,
  .actions-grid,
  .totals-grid,
  .sidebar {
    grid-template-columns: 1fr;
  }

  .column-controls button {
    min-height: 3.4rem;
    font-size: 0.76rem;
  }

  .board-grid {
    width: 100%;
    padding: 0.65rem;
    gap: 0.32rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

const loginView = document.getElementById('auth-view');
const gameView = document.getElementById('game-view');
const loginForm = document.getElementById('login-form');
const loginEmail = document.getElementById('login-email');
const loginPassword = document.getElementById('login-password');
const loginFeedback = document.getElementById('login-feedback');
const signedInName = document.getElementById('signed-in-name');
const signedInEmail = document.getElementById('signed-in-email');
const signOutButton = document.getElementById('sign-out-button');
const statusText = document.getElementById('game-status');
const feedbackText = document.getElementById('game-feedback');
const columnControls = document.getElementById('column-controls');
const boardGrid = document.getElementById('board-grid');
const redWinsEl = document.getElementById('red-wins');
const yellowWinsEl = document.getElementById('yellow-wins');
const drawsEl = document.getElementById('draws');
const newGameButton = document.getElementById('new-game-button');
const undoButton = document.getElementById('undo-button');
const redoButton = document.getElementById('redo-button');
const moveHistory = document.getElementById('move-history');

const BOARD_COLUMNS = 7;
const BOARD_ROWS = 6;
const TOKEN_KEY = 'dropline.authToken';

let authToken = localStorage.getItem(TOKEN_KEY) || '';
let currentState = null;
let isBusy = false;
let firstRenderDone = false;
const boardCells = [];
const columnButtons = [];

function createBoard() {
  boardGrid.replaceChildren();
  boardCells.length = 0;
  for (let index = 0; index < BOARD_COLUMNS * BOARD_ROWS; index += 1) {
    const cell = document.createElement('div');
    cell.className = 'cell';
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Row ${Math.floor(index / BOARD_COLUMNS) + 1}, Column ${(index % BOARD_COLUMNS) + 1}, empty`);
    boardGrid.appendChild(cell);
    boardCells.push(cell);
  }
}

function createColumnControls() {
  columnControls.replaceChildren();
  columnButtons.length = 0;
  for (let column = 1; column <= BOARD_COLUMNS; column += 1) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'secondary-button';
    button.textContent = `Drop in column ${column}`;
    button.dataset.column = String(column);
    button.addEventListener('click', () => dropInColumn(column));
    button.addEventListener('keydown', (event) => handleColumnKeydown(event, column - 1));
    columnControls.appendChild(button);
    columnButtons.push(button);
  }
}

function handleColumnKeydown(event, index) {
  if (event.key === 'ArrowLeft') {
    event.preventDefault();
    const target = columnButtons[Math.max(0, index - 1)];
    if (target) target.focus();
  } else if (event.key === 'ArrowRight') {
    event.preventDefault();
    const target = columnButtons[Math.min(columnButtons.length - 1, index + 1)];
    if (target) target.focus();
  } else if (event.key === 'Home') {
    event.preventDefault();
    columnButtons[0]?.focus();
  } else if (event.key === 'End') {
    event.preventDefault();
    columnButtons[columnButtons.length - 1]?.focus();
  }
}

function setLoading(value) {
  isBusy = value;
  signOutButton.disabled = value || !authToken;
  newGameButton.disabled = value || !currentState;
  undoButton.disabled = value || !currentState || !currentState.canUndo;
  redoButton.disabled = value || !currentState || !currentState.canRedo;
  for (const button of columnButtons) {
    button.disabled = value || !currentState || currentState.status !== 'active';
  }
}

function showLogin(message = '') {
  loginView.hidden = false;
  gameView.hidden = true;
  loginFeedback.textContent = message;
  if (!authToken) {
    loginEmail.focus();
  }
}

function showGame() {
  loginView.hidden = true;
  gameView.hidden = false;
}

function setToken(token) {
  authToken = token;
  if (token) {
    localStorage.setItem(TOKEN_KEY, token);
  } else {
    localStorage.removeItem(TOKEN_KEY);
  }
}

function authHeaders(extraHeaders = {}) {
  const headers = { ...extraHeaders };
  if (authToken) {
    headers.Authorization = `Bearer ${authToken}`;
  }
  return headers;
}

async function requestJson(path, options = {}) {
  const response = await fetch(path, {
    method: options.method || 'GET',
    headers: authHeaders(options.body ? { 'Content-Type': 'application/json' } : {}),
    body: options.body ? JSON.stringify(options.body) : undefined
  });

  let payload = {};
  try {
    payload = await response.json();
  } catch {
    payload = {};
  }

  if (!response.ok) {
    const error = new Error(payload.error || payload.message || 'Request failed');
    error.status = response.status;
    throw error;
  }

  return payload;
}

function updateStatusMessage(state) {
  statusText.textContent = state.statusMessage;
}

function updateTotals(state) {
  redWinsEl.textContent = String(state.totals.redWins);
  yellowWinsEl.textContent = String(state.totals.yellowWins);
  drawsEl.textContent = String(state.totals.draws);
}

function renderBoard(state) {
  const winningCells = new Set(state.winningCells || []);
  for (let index = 0; index < boardCells.length; index += 1) {
    const value = state.board[index];
    const row = Math.floor(index / BOARD_COLUMNS) + 1;
    const column = (index % BOARD_COLUMNS) + 1;
    const cell = boardCells[index];
    cell.className = 'cell';
    if (value === 'Red') {
      cell.classList.add('red');
    } else if (value === 'Yellow') {
      cell.classList.add('yellow');
    }
    if (winningCells.has(index)) {
      cell.classList.add('winning');
    }
    const label = `${value || 'empty'}`;
    cell.setAttribute('aria-label', `Row ${row}, Column ${column}, ${label}${winningCells.has(index) ? ', winning' : ''}`);
  }
}

function renderHistory(state) {
  moveHistory.replaceChildren();
  if (!state.appliedMoves.length) {
    const empty = document.createElement('li');
    empty.className = 'empty-history';
    empty.textContent = 'No moves yet';
    moveHistory.appendChild(empty);
    return;
  }

  for (const move of state.appliedMoves) {
    const entry = document.createElement('li');
    entry.className = 'history-item';
    const heading = document.createElement('strong');
    heading.textContent = `Move ${move.moveNumber}: ${move.color}`;
    const detail = document.createElement('span');
    detail.textContent = `Column ${move.column}, row ${move.row}`;
    entry.append(heading, detail);
    moveHistory.appendChild(entry);
  }
}

function renderSession(state) {
  currentState = state;
  signedInName.textContent = state.account.name;
  signedInEmail.textContent = state.account.email;
  updateStatusMessage(state);
  feedbackText.textContent = '';
  updateTotals(state);
  renderBoard(state);
  renderHistory(state);
  setLoading(false);
  showGame();

  if (!firstRenderDone || document.activeElement === document.body) {
    const target = state.status === 'active'
      ? columnButtons[0]
      : (state.canUndo ? undoButton : newGameButton);
    target?.focus();
  }
  firstRenderDone = true;
}

function renderLoggedOut(message = '') {
  currentState = null;
  feedbackText.textContent = '';
  setLoading(false);
  showLogin(message);
  loginPassword.value = '';
}

async function loadCurrentSession() {
  if (!authToken) {
    renderLoggedOut('');
    return;
  }

  setLoading(true);
  try {
    const state = await requestJson('/api/state');
    renderSession(state);
  } catch (error) {
    setToken('');
    renderLoggedOut(error.status === 401 ? 'Your session expired. Please sign in again.' : error.message);
  }
}

async function signIn(event) {
  event.preventDefault();
  loginFeedback.textContent = '';
  const email = loginEmail.value.trim();
  const password = loginPassword.value;

  if (!email || !password) {
    loginFeedback.textContent = 'Please enter both email and password.';
    return;
  }

  setLoading(true);
  try {
    const response = await fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password })
    });

    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(payload.error || 'Unable to sign in');
    }

    setToken(payload.token);
    loginFeedback.textContent = '';
    loginPassword.value = '';
    renderSession(payload.state);
  } catch (error) {
    setToken('');
    renderLoggedOut('');
    loginFeedback.textContent = error.message;
  } finally {
    setLoading(false);
  }
}

async function signOut() {
  if (!authToken) {
    renderLoggedOut('');
    return;
  }

  setLoading(true);
  try {
    await requestJson('/api/logout', { method: 'POST', body: {} });
  } catch {
    // Token may already be revoked; either way, leave the app signed out.
  } finally {
    setToken('');
    renderLoggedOut('');
  }
}

async function performAction(path) {
  if (isBusy || !authToken) {
    return;
  }
  setLoading(true);
  feedbackText.textContent = '';
  try {
    const payload = await requestJson(path, { method: 'POST', body: {} });
    renderSession(payload);
  } catch (error) {
    if (error.status === 401) {
      setToken('');
      renderLoggedOut('Your session expired. Please sign in again.');
      return;
    }
    feedbackText.textContent = error.message;
    setLoading(false);
  }
}

function dropInColumn(column) {
  performAction('/api/move', { column });
}

async function requestJson(path, options = {}) {
  const response = await fetch(path, {
    method: options.method || 'GET',
    headers: authHeaders(options.body ? { 'Content-Type': 'application/json' } : {}),
    body: options.body ? JSON.stringify(options.body) : undefined
  });

  let payload = {};
  try {
    payload = await response.json();
  } catch {
    payload = {};
  }

  if (!response.ok) {
    const error = new Error(payload.error || payload.message || 'Request failed');
    error.status = response.status;
    throw error;
  }

  return payload;
}

newGameButton.addEventListener('click', () => performAction('/api/new-game'));
undoButton.addEventListener('click', () => performAction('/api/undo'));
redoButton.addEventListener('click', () => performAction('/api/redo'));
signOutButton.addEventListener('click', signOut);
loginForm.addEventListener('submit', signIn);

createBoard();
createColumnControls();
setLoading(Boolean(authToken));
loadCurrentSession();

