const assert = require('assert');
const base = 'http://127.0.0.1:3000';

async function jfetch(url, options = {}) {
  const res = await fetch(url, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {})
    }
  });
  const data = await res.json().catch(() => ({}));
  return { res, data };
}

(async () => {
  const loginA = await jfetch(base + '/api/login', {
    method: 'POST',
    body: JSON.stringify({ email: 'avery@dropline.test', password: 'password123' })
  });
  assert.equal(loginA.res.ok, true);
  const tokenA = loginA.data.token;
  assert(tokenA);

  async function authFetch(path, options = {}) {
    const res = await fetch(base + path, {
      ...options,
      headers: {
        Authorization: `Bearer ${tokenA}`,
        'Content-Type': 'application/json',
        ...(options.headers || {})
      }
    });
    const data = await res.json().catch(() => ({}));
    return { res, data };
  }

  let state = loginA.data.state;
  assert.equal(state.statusMessage, "Red's turn");
  assert.equal(state.appliedMoves.length, 0);

  for (const column of [1, 1, 2, 2, 3, 3, 4]) {
    const result = await authFetch('/api/move', {
      method: 'POST',
      body: JSON.stringify({ column })
    });
    assert.equal(result.res.ok, true);
    state = result.data;
  }

  assert.equal(state.status, 'won');
  assert.equal(state.result, 'Red wins');
  assert.equal(state.totals.redWins, 1);
  assert.equal(state.canUndo, true);
  assert.equal(state.canRedo, false);
  assert.equal(state.winningCells.length, 4);
  assert.equal(state.appliedMoves.length, 7);

  const undo1 = await authFetch('/api/undo', { method: 'POST', body: '{}' });
  assert.equal(undo1.res.ok, true);
  state = undo1.data;
  assert.equal(state.status, 'active');
  assert.equal(state.result, '');
  assert.equal(state.totals.redWins, 0);
  assert.equal(state.redoCount, 1);
  assert.equal(state.appliedMoves.length, 6);

  const redo1 = await authFetch('/api/redo', { method: 'POST', body: '{}' });
  assert.equal(redo1.res.ok, true);
  state = redo1.data;
  assert.equal(state.status, 'won');
  assert.equal(state.result, 'Red wins');
  assert.equal(state.totals.redWins, 1);
  assert.equal(state.redoCount, 0);

  const loginJ = await jfetch(base + '/api/login', {
    method: 'POST',
    body: JSON.stringify({ email: 'jordan@dropline.test', password: 'password123' })
  });
  assert.equal(loginJ.res.ok, true);
  assert.equal(loginJ.data.state.appliedMoves.length, 0);
  assert.equal(loginJ.data.state.totals.redWins, 0);
  assert.equal(loginJ.data.state.statusMessage, "Red's turn");

  const oldTokenState = await fetch(base + '/api/state', {
    headers: { Authorization: `Bearer ${tokenA}` }
  });
  assert.equal(oldTokenState.status, 200);

  const logout = await authFetch('/api/logout', { method: 'POST', body: '{}' });
  assert.equal(logout.res.ok, true);

  const revoked = await fetch(base + '/api/state', { headers: { Authorization: `Bearer ${tokenA}` } });
  assert.equal(revoked.status, 401);

  console.log('verification ok');
})();
