const C = 7, R = 6;
function buildBoard(bottom) {
  const rows = [];
  for (let r = 0; r < R; r++) {
    const row = [];
    for (let c = 0; c < C; c++) {
      row.push(r % 2 === 0 ? bottom[c] : (bottom[c] === 'R' ? 'Y' : 'R'));
    }
    rows.push(row);
  }
  return rows;
}
function hasWin(board) {
  const dirs = [[1,0],[0,1],[1,1],[1,-1]];
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    const v = board[r][c];
    if (!v) continue;
    for (const [dr,dc] of dirs) {
      let count=0;
      for (let k=0;k<4;k++) {
        const rr=r+dr*k, cc=c+dc*k;
        if (rr<0||rr>=R||cc<0||cc>=C||board[rr][cc]!==v) break;
        count++;
      }
      if (count===4) return true;
    }
  }
  return false;
}
function orderFromBottom(bottom) {
  const reds=[], yellows=[];
  bottom.forEach((v, i) => (v==='R' ? reds : yellows).push(i+1));
  const order = [];
  while (reds.length || yellows.length) {
    if (reds.length) order.push(reds.shift());
    if (yellows.length) order.push(yellows.shift());
  }
  return order;
}
const choose = (arr, k, start=0, cur=[], out=[]) => {
  if (cur.length===k) { out.push(cur.slice()); return out; }
  for (let i=start;i<arr.length;i++) {
    cur.push(arr[i]);
    choose(arr,k,i+1,cur,out);
    cur.pop();
  }
  return out;
};
const cols=[1,2,3,4,5,6,7];
for (const reds of choose(cols,4)) {
  const bottom = cols.map(c => reds.includes(c) ? 'R' : 'Y');
  const board = buildBoard(bottom);
  if (!hasWin(board)) {
    console.log('FOUND', bottom.join(''));
    console.log('ORDER', JSON.stringify(orderFromBottom(bottom)));
    process.exit(0);
  }
}
console.log('none');
