const C = 7, R = 6;
const seq = Array(6).fill([1,4,2,5,3,7,6]).flat();
const board = Array(C*R).fill(null);
function idx(r,c){return r*C+c}
function landing(col){for(let r=R-1;r>=0;r--) if(!board[idx(r,col)]) return r; return -1}
function win(i,color){
  const r=Math.floor(i/C), c=i%C;
  for (const [dr,dc] of [[0,1],[1,0],[1,1],[1,-1]]) {
    let line=[i];
    let rr=r-dr, cc=c-dc;
    while(rr>=0&&rr<R&&cc>=0&&cc<C&&board[idx(rr,cc)]===color){line.unshift(idx(rr,cc)); rr-=dr; cc-=dc;}
    rr=r+dr; cc=c+dc;
    while(rr>=0&&rr<R&&cc>=0&&cc<C&&board[idx(rr,cc)]===color){line.push(idx(rr,cc)); rr+=dr; cc+=dc;}
    if (line.length>=4) return true;
  }
  return false;
}
let color='Red';
for (let step=0; step<seq.length; step++) {
  const col=seq[step]-1;
  const row=landing(col);
  if (row<0) throw new Error('full col at step '+step);
  const i=idx(row,col);
  board[i]=color;
  if (win(i,color)) {
    console.log('WIN at step', step+1, color, 'col', col+1, 'row', row+1);
    process.exit(0);
  }
  color = color === 'Red' ? 'Yellow' : 'Red';
}
console.log('no win, final full?', board.every(Boolean));
