const assert = require('assert');
const base = 'http://127.0.0.1:3000';
const seq = Array(6).fill([1,4,2,5,3,7,6]).flat();

async function login(email) {
  const res = await fetch(base + '/api/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password: 'password123' })
  });
  const data = await res.json();
  assert(res.ok, JSON.stringify(data));
  return data;
}

async function auth(token, path, body = {}) {
  const res = await fetch(base + path, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  });
  const data = await res.json().catch(() => ({}));
  return { res, data };
}

(async () => {
  const loginJ = await login('jordan@dropline.test');
  const token = loginJ.token;
  let state = loginJ.state;
  assert.equal(state.appliedMoves.length, 0);
  assert.equal(state.totals.draws, 0);

  for (const column of seq) {
    const result = await auth(token, '/api/move', { column });
    assert(result.res.ok, JSON.stringify(result.data));
    state = result.data;
  }

  assert.equal(state.status, 'draw');
  assert.equal(state.result, 'Draw');
  assert.equal(state.totals.draws, 1);
  assert.equal(state.winningCells.length, 0);
  assert.equal(state.appliedMoves.length, 42);
  assert.equal(state.canUndo, true);
  assert.equal(state.canRedo, false);

  const undo = await auth(token, '/api/undo');
  assert(undo.res.ok, JSON.stringify(undo.data));
  state = undo.data;
  assert.equal(state.status, 'active');
  assert.equal(state.result, '');
  assert.equal(state.totals.draws, 0);
  assert.equal(state.redoCount, 1);
  assert.equal(state.appliedMoves.length, 41);

  const redo = await auth(token, '/api/redo');
  assert(redo.res.ok, JSON.stringify(redo.data));
  state = redo.data;
  assert.equal(state.status, 'draw');
  assert.equal(state.result, 'Draw');
  assert.equal(state.totals.draws, 1);
  assert.equal(state.redoCount, 0);
  assert.equal(state.appliedMoves.length, 42);

  console.log('draw verification ok');
})();
